Dataspatium.assets.register("presets/api/prh-ytj.api.json","text","{\n  \"format\": \"dataspatium-api/1\",\n  \"id\": \"prh-ytj\",\n  \"name\": \"Företags- och organisationsdatasystemet YTJ (PRH)\",\n  \"publisher\": \"Patent- och registerstyrelsen (PRH)\",\n  \"description\": \"Finlands företagsregister som öppna data: namn, FO-nummer, företagsform, huvudbransch, adresser och registreringar. Sök på namn, ort, FO-nummer eller bransch. Namnhistorik, adresser och branscher ligger som JSON-text i sina kolumner.\",\n  \"docs\": \"https://avoindata.prh.fi/sv/ytj\",\n  \"license\": { \"name\": \"CC BY 4.0\", \"url\": \"https://creativecommons.org/licenses/by/4.0/\" },\n  \"level\": 1,\n  \"country\": \"FI\",\n  \"baseUrl\": \"https://avoindata.prh.fi/opendata-ytj-api/v3\",\n  \"auth\": { \"type\": \"none\" },\n  \"rateLimit\": { \"requests\": 3, \"perSeconds\": 1 },\n  \"endpoints\": [\n    {\n      \"id\": \"companies\",\n      \"name\": \"Sök företag\",\n      \"description\": \"Företag som matchar sökvillkoren. Minst ett villkor behövs; högst fem sidor hämtas.\",\n      \"method\": \"GET\",\n      \"path\": \"/companies\",\n      \"params\": [\n        { \"name\": \"name\", \"in\": \"query\", \"label\": \"Namn (del av)\", \"type\": \"string\", \"example\": \"Nokia\" },\n        { \"name\": \"location\", \"in\": \"query\", \"label\": \"Ort\", \"type\": \"string\", \"example\": \"Helsinki\" },\n        { \"name\": \"businessId\", \"in\": \"query\", \"label\": \"FO-nummer\", \"type\": \"string\", \"example\": \"0112038-9\" },\n        { \"name\": \"mainBusinessLine\", \"in\": \"query\", \"label\": \"Huvudbransch (TOL-kod)\", \"type\": \"string\", \"example\": \"62010\" },\n        { \"name\": \"registrationDateStart\", \"in\": \"query\", \"label\": \"Registrerad från\", \"type\": \"date\" },\n        { \"name\": \"registrationDateEnd\", \"in\": \"query\", \"label\": \"Registrerad till\", \"type\": \"date\" }\n      ],\n      \"pagination\": { \"type\": \"page\", \"param\": \"page\", \"start\": 1, \"maxPages\": 5 },\n      \"response\": { \"format\": \"json\", \"path\": \"companies\" },\n      \"dataset\": { \"name\": \"YTJ företag: {name} {location} {businessId}\" }\n    }\n  ],\n  \"notes\": \"Ange källa: Patent- och registerstyrelsen.\",\n  \"i18n\": {\n    \"en\": { \"name\": \"Business Information System YTJ (PRH)\", \"publisher\": \"Finnish Patent and Registration Office (PRH)\", \"description\": \"Finland's company register as open data: name, business ID, company form, main line of business, addresses and registrations. Search by name, location, business ID or line of business. Name history, addresses and lines of business are JSON text in their columns.\", \"notes\": \"Cite the source: Finnish Patent and Registration Office.\", \"endpoints\": { \"companies\": { \"name\": \"Search companies\", \"description\": \"Companies matching the criteria. At least one criterion is needed; at most five pages are fetched.\", \"params\": { \"name\": { \"label\": \"Name (part of)\" }, \"location\": { \"label\": \"Location\" }, \"businessId\": { \"label\": \"Business ID\" }, \"mainBusinessLine\": { \"label\": \"Main line of business (TOL code)\" }, \"registrationDateStart\": { \"label\": \"Registered from\" }, \"registrationDateEnd\": { \"label\": \"Registered until\" } } } }, \"dataset\": { \"companies\": \"YTJ companies: {name} {location} {businessId}\" } },\n    \"da\": { \"name\": \"Virksomheds- og organisationsdatasystemet YTJ (PRH)\", \"publisher\": \"Patent- og registerstyrelsen (PRH)\", \"description\": \"Finlands virksomhedsregister som åbne data: navn, FO-nummer, virksomhedsform, hovedbranche, adresser og registreringer. Søg på navn, by, FO-nummer eller branche. Navnehistorik, adresser og brancher ligger som JSON-tekst i deres kolonner.\", \"notes\": \"Angiv kilde: Patent- og registerstyrelsen.\", \"endpoints\": { \"companies\": { \"name\": \"Søg virksomheder\", \"description\": \"Virksomheder, der matcher søgekriterierne. Mindst ét kriterium kræves; højst fem sider hentes.\", \"params\": { \"name\": { \"label\": \"Navn (del af)\" }, \"location\": { \"label\": \"By\" }, \"businessId\": { \"label\": \"FO-nummer\" }, \"mainBusinessLine\": { \"label\": \"Hovedbranche (TOL-kode)\" }, \"registrationDateStart\": { \"label\": \"Registreret fra\" }, \"registrationDateEnd\": { \"label\": \"Registreret til\" } } } }, \"dataset\": { \"companies\": \"YTJ virksomheder: {name} {location} {businessId}\" } },\n    \"nb\": { \"name\": \"Foretaks- og organisasjonsdatasystemet YTJ (PRH)\", \"publisher\": \"Patent- og registerstyret (PRH)\", \"description\": \"Finlands foretaksregister som åpne data: navn, FO-nummer, foretaksform, hovedbransje, adresser og registreringer. Søk på navn, sted, FO-nummer eller bransje. Navnehistorikk, adresser og bransjer ligger som JSON-tekst i sine kolonner.\", \"notes\": \"Oppgi kilde: Patent- og registerstyret.\", \"endpoints\": { \"companies\": { \"name\": \"Søk foretak\", \"description\": \"Foretak som matcher søkekriteriene. Minst ett kriterium trengs; høyst fem sider hentes.\", \"params\": { \"name\": { \"label\": \"Navn (del av)\" }, \"location\": { \"label\": \"Sted\" }, \"businessId\": { \"label\": \"FO-nummer\" }, \"mainBusinessLine\": { \"label\": \"Hovedbransje (TOL-kode)\" }, \"registrationDateStart\": { \"label\": \"Registrert fra\" }, \"registrationDateEnd\": { \"label\": \"Registrert til\" } } } }, \"dataset\": { \"companies\": \"YTJ foretak: {name} {location} {businessId}\" } },\n    \"fi\": { \"name\": \"Yritys- ja yhteisötietojärjestelmä YTJ (PRH)\", \"publisher\": \"Patentti- ja rekisterihallitus (PRH)\", \"description\": \"Suomen yritysrekisteri avoimena datana: nimi, Y-tunnus, yritysmuoto, päätoimiala, osoitteet ja rekisteröinnit. Hae nimellä, paikkakunnalla, Y-tunnuksella tai toimialalla. Nimihistoria, osoitteet ja toimialat ovat JSON-tekstinä omissa sarakkeissaan.\", \"notes\": \"Mainitse lähde: Patentti- ja rekisterihallitus.\", \"endpoints\": { \"companies\": { \"name\": \"Hae yrityksiä\", \"description\": \"Hakuehtoja vastaavat yritykset. Vähintään yksi ehto tarvitaan; enintään viisi sivua noudetaan.\", \"params\": { \"name\": { \"label\": \"Nimi (osa)\" }, \"location\": { \"label\": \"Paikkakunta\" }, \"businessId\": { \"label\": \"Y-tunnus\" }, \"mainBusinessLine\": { \"label\": \"Päätoimiala (TOL-koodi)\" }, \"registrationDateStart\": { \"label\": \"Rekisteröity alkaen\" }, \"registrationDateEnd\": { \"label\": \"Rekisteröity asti\" } } } }, \"dataset\": { \"companies\": \"YTJ yritykset: {name} {location} {businessId}\" } },\n    \"is\": { \"name\": \"Fyrirtækjaskrá Finnlands YTJ (PRH)\", \"publisher\": \"Einkaleyfa- og skráningarstofa Finnlands (PRH)\", \"description\": \"Fyrirtækjaskrá Finnlands sem opin gögn: heiti, fyrirtækjanúmer, rekstrarform, aðalatvinnugrein, heimilisföng og skráningar. Leitaðu eftir heiti, stað, fyrirtækjanúmeri eða atvinnugrein. Nafnasaga, heimilisföng og atvinnugreinar eru JSON-texti í sínum dálkum.\", \"notes\": \"Tilgreindu heimild: Einkaleyfa- og skráningarstofa Finnlands.\", \"endpoints\": { \"companies\": { \"name\": \"Leita að fyrirtækjum\", \"description\": \"Fyrirtæki sem passa við leitarskilyrðin. Minnst eitt skilyrði þarf; að hámarki fimm síður eru sóttar.\", \"params\": { \"name\": { \"label\": \"Heiti (hluti af)\" }, \"location\": { \"label\": \"Staður\" }, \"businessId\": { \"label\": \"Fyrirtækjanúmer\" }, \"mainBusinessLine\": { \"label\": \"Aðalatvinnugrein (TOL-kóði)\" }, \"registrationDateStart\": { \"label\": \"Skráð frá\" }, \"registrationDateEnd\": { \"label\": \"Skráð til\" } } } }, \"dataset\": { \"companies\": \"YTJ fyrirtæki: {name} {location} {businessId}\" } }\n  }\n}\n");
